From c6504be53972cd57326196eb2a18b2b182c26c5c Mon Sep 17 00:00:00 2001
From: Vinod Koul <vkoul@kernel.org>
Date: Fri, 26 Apr 2019 22:30:27 +0530
Subject: [PATCH] dmaengine: stm32-dma: Fix unsigned variable compared with
 zero

Commit f4fd2ec08f17: ("dmaengine: stm32-dma: use platform_get_irq()") used
unsigned variable irq to store the results and check later for negative
errors, so update the code to use signed variable for this

Fixes: f4fd2ec08f17 ("dmaengine: stm32-dma: use platform_get_irq()")
Reported-by: kbuild test robot <lkp@intel.com>
Reported-by: Julia Lawall <julia.lawall@lip6.fr>
Acked-by: Julia Lawall <julia.lawall@lip6.fr>
Signed-off-by: Vinod Koul <vkoul@kernel.org>

diff --git a/drivers/dma/stm32-dma.c b/drivers/dma/stm32-dma.c
index 33068185c0fe..dde796686736 100644
--- a/drivers/dma/stm32-dma.c
+++ b/drivers/dma/stm32-dma.c
@@ -1303,13 +1303,15 @@ static int stm32_dma_probe(struct platform_device *pdev)
 	for (i = 0; i < STM32_DMA_MAX_CHANNELS; i++) {
 		chan = &dmadev->chan[i];
 		chan->irq = platform_get_irq(pdev, i);
-		if (chan->irq < 0)  {
-			ret = chan->irq;
+		ret = platform_get_irq(pdev, i);
+		if (ret < 0)  {
 			if (ret != -EPROBE_DEFER)
 				dev_err(&pdev->dev,
 					"No irq resource for chan %d\n", i);
 			goto err_unregister;
 		}
+		chan->irq = ret;
+
 		ret = devm_request_irq(&pdev->dev, chan->irq,
 				       stm32_dma_chan_irq, 0,
 				       dev_name(chan2dev(chan)), chan);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by using an unsigned variable to store the result of `platform_get_irq()`, which can return negative error codes. This led to incorrect comparisons when checking for errors, as unsigned variables cannot represent negative values, resulting in potential misinterpretation of error conditions.

        Commit message:
        dmaengine: stm32-dma: Fix unsigned variable compared with
 zero

Commit f4fd2ec08f17: ("dmaengine: stm32-dma: use platform_get_irq()") used
unsigned variable irq to store the results and check later for negative
errors, so update the code to use signed variable for this

Fixes: f4fd2ec08f17 ("dmaengine: stm32-dma: use platform_get_irq()")
Reported-by: kbuild test robot <lkp@intel.com>
Reported-by: Julia Lawall <julia.lawall@lip6.fr>
Acked-by: Julia Lawall <julia.lawall@lip6.fr>
Signed-off-by: Vinod Koul <vkoul@kernel.org>  

        Patch:

 static int stm32_dma_probe(struct platform_device *pdev)
 {
 	struct stm32_dma_chan *chan;
 	struct stm32_dma_device *dmadev;
 	struct dma_device *dd;
 	const struct of_device_id *match;
 	struct resource *res;
 	int i, ret;

 	match = of_match_device(stm32_dma_of_match, &pdev->dev);
 	if (!match) {
 		dev_err(&pdev->dev, "Error: No device match found\n");
 		return -ENODEV;
 	}

 	dmadev = devm_kzalloc(&pdev->dev, sizeof(*dmadev), GFP_KERNEL);
 	if (!dmadev)
 		return -ENOMEM;

 	dd = &dmadev->ddev;

 	res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
 	dmadev->base = devm_ioremap_resource(&pdev->dev, res);
 	if (IS_ERR(dmadev->base))
 		return PTR_ERR(dmadev->base);

 	dmadev->clk = devm_clk_get(&pdev->dev, NULL);
 	if (IS_ERR(dmadev->clk)) {
 		dev_err(&pdev->dev, "Error: Missing controller clock\n");
 		return PTR_ERR(dmadev->clk);
 	}

 	ret = clk_prepare_enable(dmadev->clk);
 	if (ret < 0) {
 		dev_err(&pdev->dev, "clk_prep_enable error: %d\n", ret);
 		return ret;
 	}

 	dmadev->mem2mem = of_property_read_bool(pdev->dev.of_node,
 						"st,mem2mem");

 	dmadev->rst = devm_reset_control_get(&pdev->dev, NULL);
 	if (!IS_ERR(dmadev->rst)) {
 		reset_control_assert(dmadev->rst);
 		udelay(2);
 		reset_control_deassert(dmadev->rst);
 	}

 	dma_cap_set(DMA_SLAVE, dd->cap_mask);
 	dma_cap_set(DMA_PRIVATE, dd->cap_mask);
 	dma_cap_set(DMA_CYCLIC, dd->cap_mask);
 	dd->device_alloc_chan_resources = stm32_dma_alloc_chan_resources;
 	dd->device_free_chan_resources = stm32_dma_free_chan_resources;
 	dd->device_tx_status = stm32_dma_tx_status;
 	dd->device_issue_pending = stm32_dma_issue_pending;
 	dd->device_prep_slave_sg = stm32_dma_prep_slave_sg;
 	dd->device_prep_dma_cyclic = stm32_dma_prep_dma_cyclic;
 	dd->device_config = stm32_dma_slave_config;
 	dd->device_terminate_all = stm32_dma_terminate_all;
 	dd->device_synchronize = stm32_dma_synchronize;
 	dd->src_addr_widths = BIT(DMA_SLAVE_BUSWIDTH_1_BYTE) |
 		BIT(DMA_SLAVE_BUSWIDTH_2_BYTES) |
 		BIT(DMA_SLAVE_BUSWIDTH_4_BYTES);
 	dd->dst_addr_widths = BIT(DMA_SLAVE_BUSWIDTH_1_BYTE) |
 		BIT(DMA_SLAVE_BUSWIDTH_2_BYTES) |
 		BIT(DMA_SLAVE_BUSWIDTH_4_BYTES);
 	dd->directions = BIT(DMA_DEV_TO_MEM) | BIT(DMA_MEM_TO_DEV);
 	dd->residue_granularity = DMA_RESIDUE_GRANULARITY_BURST;
 	dd->max_burst = STM32_DMA_MAX_BURST;
 	dd->dev = &pdev->dev;
 	INIT_LIST_HEAD(&dd->channels);

 	if (dmadev->mem2mem) {
 		dma_cap_set(DMA_MEMCPY, dd->cap_mask);
 		dd->device_prep_dma_memcpy = stm32_dma_prep_dma_memcpy;
 		dd->directions |= BIT(DMA_MEM_TO_MEM);
 	}

 	for (i = 0; i < STM32_DMA_MAX_CHANNELS; i++) {
 		chan = &dmadev->chan[i];
 		chan->id = i;
 		chan->vchan.desc_free = stm32_dma_desc_free;
 		vchan_init(&chan->vchan, dd);
 	}

 	ret = dma_async_device_register(dd);
 	if (ret)
 		goto clk_free;

 	for (i = 0; i < STM32_DMA_MAX_CHANNELS; i++) {
 		chan = &dmadev->chan[i];
 		chan->irq = platform_get_irq(pdev, i);
-		if (chan->irq < 0)  {
-			ret = chan->irq;
+		ret = platform_get_irq(pdev, i);
+		if (ret < 0)  {
 			if (ret != -EPROBE_DEFER)
 				dev_err(&pdev->dev,
 					"No irq resource for chan %d\n", i);
 			goto err_unregister;
 		}
+		chan->irq = ret;
+
 		ret = devm_request_irq(&pdev->dev, chan->irq,
 				       stm32_dma_chan_irq, 0,
 				       dev_name(chan2dev(chan)), chan);
 		if (ret) {
 			dev_err(&pdev->dev,
 				"request_irq failed with err %d channel %d\n",
 				ret, i);
 			goto err_unregister;
 		}
 	}

 	ret = of_dma_controller_register(pdev->dev.of_node,
 					 stm32_dma_of_xlate, dmadev);
 	if (ret < 0) {
 		dev_err(&pdev->dev,
 			"STM32 DMA DMA OF registration failed %d\n", ret);
 		goto err_unregister;
 	}

 	platform_set_drvdata(pdev, dmadev);

 	pm_runtime_set_active(&pdev->dev);
 	pm_runtime_enable(&pdev->dev);
 	pm_runtime_get_noresume(&pdev->dev);
 	pm_runtime_put(&pdev->dev);

 	dev_info(&pdev->dev, "STM32 DMA driver registered\n");

 	return 0;

 err_unregister:
 	dma_async_device_unregister(dd);
 clk_free:
 	clk_disable_unprepare(dmadev->clk);

 	return ret;
 }



